const u = $input.first().json;
let kind = 'other';
if (u.callback_query) kind = 'callback';
else if (u.message && u.message.voice) kind = 'voice';
else if (u.message && u.message.photo) kind = (u.message.caption ? 'photo' : 'photo_nocap');
else if (u.message && u.message.text) kind = 'text';
const allowed = [YOUR_TELEGRAM_ID, 916602267];
const fromId = u.callback_query ? u.callback_query.from.id : (u.message && u.message.from ? u.message.from.id : 0);
if (!allowed.includes(fromId)) kind = 'unauthorized';
let text = (u.message && u.message.text) ? u.message.text : ((u.message && u.message.caption) ? u.message.caption : '');
let videoUrl = null, editOriginal = null, editPhotoId = null;
if (kind === 'photo') {
  if (u.message.caption) { editPhotoId = u.message.photo.slice(-1)[0].file_id; text = u.message.caption; }
  else kind = 'photo_nocaption';
}
if (kind === 'photo') { editPhotoId = u.message.photo.slice(-1)[0].file_id; }
if (kind === 'text') {
  const m = text.match(/https?:\/\/\S+\.(mp4|mov|webm|m4v)(\?\S*)?/i);
  if (m) { videoUrl = m[0]; kind = 'video'; text = text.replace(m[0], '').trim(); }
  const rt = u.message.reply_to_message;
  if (rt && rt.from && rt.from.is_bot) {
    const rtText = rt.text || rt.caption || '';
    if (/причину відхилення/i.test(rtText)) {
      kind = 'reject_comment';
    } else {
      kind = 'edit';
      editOriginal = rtText;
      if (rt.photo) editPhotoId = rt.photo.slice(-1)[0].file_id;
    }
  }
}
return [{ json: { kind, fromId, userText: text.replace(/^\/post\s*/i, ''), videoUrl, editOriginal, editPhotoId, update: u } }];

const includePromo = Math.random() < 0.2;
const promoLine = includePromo
  ? 'Наприкінці посту додай ОДНЕ коротке ненав'язливе речення про AI News Bot: компанія впроваджує AI-рішення, Computer Vision та відео/аудіо аналітику для бізнесу.'
  : 'НЕ згадуй компанію AI News Bot у тексті цього посту — без жодної реклами.';
const j = $input.first().json;
const len = (j.videoUrl || j.editPhotoId) ? '600-850' : '900-1600';
const system = "Ти — редактор Telegram-каналу «AI Love You» компанії AI News Bot (example.com, example.com). Пишеш про практичний AI для бізнесу.

Аудиторія: власники бізнесу, директори, маркетологи, керівники ритейлу, e-commerce, логістики, сервісу. Вони не технарі.
Мова: українська.
Обсяг: __LEN__ символів. Жорстка межа — не більше 950 символів разом із пробілами.

Стиль — дуже просто, для бізнесу:
- Короткі речення. Пиши як людина, а не як прес-реліз.
- Без технічного жаргону. Якщо термін необхідний — поясни його простими словами в пів речення.
- Мова бізнес-вигод: гроші, час, клієнти, ROI, економія, менше втрат, більше продажів.

Формат:
- Розбий текст на 2-4 короткі абзаци з порожнім рядком між ними.
- Додай 2-3 доречні емодзі: один у заголовку, по одному на ключових абзацах. Не більше.
- Без markdown-форматування і хештегів. Не вставляй URL у текст — посилання на джерело додається автоматично після посту.

Структура посту:
1. Чіпкий заголовок з емодзі (1 рядок).
2. Суть простими словами: що сталося і чому це важливо.
3. Практичний висновок: що це дає бізнесу — власнику магазину, ритейлеру, e-commerce.
4. Коротке питання до читачів у кінці (опційно).

Якщо джерело — дослідження, звіт або наукова стаття (Arxiv, McKinsey, університети, аналітичні агенції):
- подай пост як превʼю дослідження: 2-3 найцікавіші цифри або висновки;
- обовʼязково назви, чиє це дослідження (компанія/університет);
- додай одне речення власної думки: що це означає для бізнесу вже зараз.

Тематика каналу: ритейл та e-commerce (персоналізація, прогнозування попиту, динамічні ціни, рекомендації), впровадження AI у бізнесі (кейси, ROI, помилки), Computer Vision і відео/аудіо аналітика (розпізнавання, контроль якості, черги, безпека — це профіль AI News Bot Vision), дані й аналітика, автоматизація процесів і RPA, кібербезпека та ризики AI, прикладні дослідження з користю для бізнесу.

__PROMO__
Будь чесний: якщо це реклама AI-інструменту, оціни критично.".replace('__LEN__', len).replace('__PROMO__', promoLine);
let userPrompt;
if (j.kind === 'edit') {
  userPrompt = `Ось поточна версія посту:
---
${j.editOriginal}
---
Правки від редактора: ${j.userText}

Перепиши пост з урахуванням правок, зберігаючи стиль і формат каналу.`;
} else {
  userPrompt = `Напиши пост для каналу за цією ідеєю від команди:
${j.userText || ''}

Зроби його корисним для бізнесу з акцентом на практичну цінність для ритейлу, e-commerce, Computer Vision, даних, автоматизації або кібербезпеки.`;
}
return [{ json: { systemPrompt: system, userPrompt, videoUrl: j.videoUrl || null, editPhotoId: j.editPhotoId || null } }];

const items=$input.all();
for(const item of items){ if(item.binary){ for(const k of Object.keys(item.binary)){ item.binary[k].fileName='voice.ogg'; item.binary[k].mimeType='audio/ogg'; item.binary[k].fileExtension='ogg'; } } }
return items;

const r = $input.first().json;
const results = r.results || [];
const top = results[0] || {};
const images = r.images || [];
const ut = $('Класифікація').first().json.userText;
return [{ json: {
  userText: ut,
  title: top.title || '',
  url: top.url || '',
  content: (top.content || '').slice(0, 2000),
  tavilyImage: images.length ? images[0] : null
} }];

const src = $('Вибір статті').first().json;
const html = String(($input.first().json && ($input.first().json.data || $input.first().json.body)) || '');
let m = html.match(/property=["']og:image["'][^>]*content=["']([^"']+)["']/i) || html.match(/content=["']([^"']+)["'][^>]*property=["']og:image["']/i);
let cand = (m && m[1]) || src.tavilyImage || null;
if (cand && !/^https?:\/\//i.test(cand)) cand = null;
if (cand && !/\.(jpe?g|png)(\?|$)/i.test(cand)) cand = null;
if (cand && /logo|favicon|sprite|placeholder/i.test(cand)) cand = null;
const imageUrl = cand;
return [{ json: { userText: src.userText, title: src.title, url: src.url, content: src.content, imageUrl } }];
